42	{
43	#if defined(__aarch64__)
44	    unsigned long hwcap = getauxval(AT_HWCAP);
45	    if ((hwcap & HWCAP_SVE) == 0) {
46	        log_skip(CpuNotSupportedSkipCategory,
47	                 "to be implemented (placeholder): ARM SVE required for movbe_dump_probe_c_sve");
48	        return EXIT_SKIP;
49	    }
50	#endif
51	    auto *data = (movbe_dump_probe_c_sve_data *)malloc(sizeof(movbe_dump_probe_c_sve_data));
52	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
53	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
54	
55	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
56	        data->input[i] = random32();
57	    }
58	
59	    test->data = data;
60	    return EXIT_SUCCESS;
61	}
62	
63	#if defined(__aarch64__)
64	static int movbe_dump_probe_c_sve_run(struct test *test, int cpu)
65	{
66	    (void)cpu;
67	    auto *data = (movbe_dump_probe_c_sve_data *)test->data;
68	
69	    /* bswap32 的 svtbl 索引: 每元素 [3,2,1,0] */
70	    static const uint8_t idx4[4] = {3, 2, 1, 0};
71	
72	    const int lanes = svcntw();
73	    uint8_t vidx_bytes[64];
74	    for (int i = 0; i < lanes && i < 16; ++i)
75	        for (int b = 0; b < 4; ++b)
76	            vidx_bytes[i * 4 + b] = (uint8_t)(i * 4 + idx4[b]);
77	    svbool_t pg_batch = svwhilelt_b8((uint64_t)0, (uint64_t)(lanes < 16 ? lanes * 4 : 64));
78	    svuint8_t vidx = svld1_u8(pg_batch, vidx_bytes);
79	
80	    /* 每线程私有副本 (SLF 探针, 消除多写者竞争) */
81	    static thread_local uint32_t *priv_input = nullptr;
82	    if (!priv_input) priv_input = (uint32_t *)aligned_alloc(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
83	    memcpy(priv_input, data->input, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
84	
85	    TEST_LOOP(test, 1 << 13) {
86	        /* 每外层迭代重置私有副本 (store-back 污染下一遍; 原版标量逐 i 独立访问无此问题) */
87	        memcpy(priv_input, data->input, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
88	        for (size_t base = 0; base < MOVBE_BUFFER_SIZE; base += lanes) {
89	            int n = (MOVBE_BUFFER_SIZE - base < (size_t)lanes) ? (int)(MOVBE_BUFFER_SIZE - base) : lanes;
90	            svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(n * 4));
91	
92	            /* 载入 n 个 32-bit 元素 (向量) → 字节级重排 */
93	            uint8_t in_bytes[64];
94	            memcpy(in_bytes, priv_input + base, n * 4);
95	            svuint8_t vswapped = svtbl_u8(svld1_u8(pg, in_bytes), vidx);
96	
