98	             * asm memory barrier 阻断编译器对 store/reload 序列的优化
99	             * (无屏障时编译器消除真实 reload, 破坏 SLF 语义)。 */
100	            memcpy(priv_input + base, in_bytes, n * 4);
101	            /* ★ 直接 store 到输入位置 (SLF 核心, svst1 直打堆无栈中转) */
102	            svst1_u8(pg, (uint8_t *)(priv_input + base), vswapped);
103	            __asm__ volatile("" ::: "memory");
104	            /* ★ reload: svld1 直接读刚写过的输入位置 (真实 store→load 转发) */
105	            svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)(priv_input + base));
106	
107	            /* 再交换一次还原 (同一索引表, svtbl 可逆) */
108	            svuint8_t vrestored = svtbl_u8(reloaded, vidx);
109	            uint8_t out_bytes[64];
110	            svst1_u8(pg, out_bytes, vrestored);
