117	                    uint32_t inputv = data->input[base + i];
118	                    uint32_t golden = inputv;
119	                    uint32_t actual = restored[i];
120	                    uint32_t xorv = golden ^ actual;
121	                    unsigned char *ib = (unsigned char *)&inputv;
122	                    unsigned char *gb = (unsigned char *)&golden;
123	                    unsigned char *ab = (unsigned char *)&actual;
124	                    unsigned char *xb = (unsigned char *)&xorv;
125	                    log_error("MovBE-SVE-dump: Round-trip failed at index %u: "
126	                              "input=0x%08X golden=0x%08X actual=0x%08X xor=0x%08X | "
127	                              "bytes[b3 b2 b1 b0] input=%02X%02X%02X%02X "
128	                              "golden=%02X%02X%02X%02X actual=%02X%02X%02X%02X "
129	                              "xor=%02X%02X%02X%02X",
130	                              (unsigned)(base + i), inputv, golden, actual, xorv,
131	                              ib[3], ib[2], ib[1], ib[0],
132	                              gb[3], gb[2], gb[1], gb[0],
133	                              ab[3], ab[2], ab[1], ab[0],
134	                              xb[3], xb[2], xb[1], xb[0]);
135	                    report_fail_msg("MovBE-SVE: Round-trip failed at index %u",
136	                                    (unsigned)(base + i));
137	                }
138	            }
139	        }
140	    }
141	
142	    return EXIT_SUCCESS;
143	}
