146	{
147	    (void)test; (void)cpu;
148	    log_skip(CpuNotSupportedSkipCategory,
149	             "to be implemented (placeholder): ARM SVE required for movbe_dump_probe_c_sve");
150	    return EXIT_SKIP;
151	}
152	#endif
