```cpp
static bool slf_sweep_selfcheck_width(int width)  // returns false on mismatch
{
    const uint64_t vbytes = svcntb();
    uint8_t vidx_bytes[SVE_MAX_VECTOR_BYTES];
    build_index_table(vidx_bytes, width, vbytes);
    svbool_t pg_full = svwhilelt_b8((uint64_t)0, vbytes);
    svuint8_t vidx = svld1_u8(pg_full, vidx_bytes);

    uint8_t src[256] __attribute__((aligned(16)));  // or just plain array
    uint8_t dst[256];
    uint64_t checked = 0;
    while (checked < N) {
        uint64_t count = vbytes / width;            // elements in this batch
        if (count > N - checked) count = N - checked; // partial final batch
        uint64_t nbytes = count * width;
        svbool_t pg = svwhilelt_b8((uint64_t)0, nbytes);
        // fill src with random values of width W
        for (uint64_t e = 0; e < count; ++e) {
            uint64_t rv = random64();  // hmm — random32 vs random64
            switch (width) {
            case 2: { uint16_t v = ...; memcpy(src + e*2, &v, 2); } break;
            ...
            }
        }
        svuint8_t v = svld1_u8(pg, src);
        svuint8_t p = svtbl_u8(v, vidx);
        svst1_u8(pg, dst, p);
        for (uint64_t e = 0; e < count; ++e) {
            // compare dst[e*W..e*W+W) vs bswap(src element)
            uint64_t expected = bswap of src element
            if (memcmp(dst + e*width, &expected, width) != 0) return false / report;
        }
        checked += count;
    }
    return true;
}
```

