    svuint8_t vidx = svld1_u8(pg_full, vidx_bytes);

    uint8_t src[SVE_MAX_VECTOR_BYTES];
    uint8_t dst[SVE_MAX_VECTOR_BYTES];
    uint64_t checked = 0;
    while (checked < SLF_SWEEP_SELFCHECK_VECS) {
        uint64_t count = vbytes / (uint64_t)width;
